WRITE_OFF_GUARD_SQL = r"""
CREATE FUNCTION invoicing_guard_write_off() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ledger_purge_allowed() THEN
        RETURN coalesce(NEW, OLD);
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'A receivable written off cannot be deleted; void it instead.' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'posted' OR NEW.amount <= 0 OR NOT EXISTS (
            SELECT 1 FROM invoicing_invoice i JOIN ledger_journalentry j ON j.id = NEW.journal_entry_id
             WHERE i.id = NEW.invoice_id AND i.organization_id = NEW.organization_id AND i.kind = 'sales'
               AND i.status IN ('issued', 'partial') AND NEW.date >= i.date
               AND NEW.amount = i.total - i.amount_paid - i.amount_credited - i.amount_written_off
               AND j.organization_id = NEW.organization_id AND j.status = 'posted'
        ) THEN
            RAISE EXCEPTION 'A write-off takes the whole balance of an open sales invoice, with a posted journal entry.'
                USING ERRCODE = 'integrity_constraint_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF (to_jsonb(NEW) - 'status' - 'updated_at' - 'created_by_id') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'updated_at' - 'created_by_id')
       OR (NEW.created_by_id IS DISTINCT FROM OLD.created_by_id AND NEW.created_by_id IS NOT NULL)
       OR (NEW.status IS DISTINCT FROM OLD.status AND (
           OLD.status <> 'posted' OR NEW.status <> 'void'
           OR NOT EXISTS (SELECT 1 FROM ledger_journalentry r WHERE r.reversal_of_id = OLD.journal_entry_id AND r.status = 'posted')))
    THEN
        RAISE EXCEPTION 'A write-off can only be voided, after its journal entry is reversed.' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER invoicing_receivablewriteoff_guard BEFORE INSERT OR UPDATE OR DELETE ON invoicing_receivablewriteoff
    FOR EACH ROW EXECUTE FUNCTION invoicing_guard_write_off();
""" + TRAIL.track_sql("invoicing_receivablewriteoff", "organization_id")

